SET NAMES utf8mb4;

INSERT IGNORE INTO `hustles`
  (`name`, `slug`, `emoji`, `category`, `description`, `income_min`, `income_max`,
   `income_period`, `difficulty`, `capital_needed`, `skills_needed`, `location_tags`,
   `steps`, `is_featured`)
VALUES
('WhatsApp Status Advertising Agency', 'whatsapp-status-ads', '📲', 'digital', 'Sell ad space on your WhatsApp status to local businesses. With 500+ contacts, businesses pay ₦2k–₦10k per status post to reach your audience.', 15000, 40000, 'day', 'beginner', 0, '["No Capital", "WhatsApp", "Social Media"]', '["Online", "Lagos", "Abuja"]', '["Grow WhatsApp contacts to 500+ (export from all your phone numbers, social media DMs)", "Create a rate card: \\u20a63k/single status, \\u20a615k/week campaign, \\u20a650k/month", "Approach local businesses \\u2014 suya sellers, fashion stores, event planners, restaurants", "Post their ads as statuses with your own caption flair for authenticity", "Scale: recruit 10 friends with large contact lists, take 30% management cut"]', 1),
('Instagram Shoutout Brokerage', 'instagram-shoutout-broker', '📣', 'social', 'Connect businesses with Instagram influencers for shoutouts and earn 20–30% commission from both sides. No followers needed — just connections and sales skill.', 30000, 80000, 'week', 'beginner', 0, '["No Capital", "Commission", "Social Media"]', '["Online", "Lagos", "Abuja"]', '["Build a list of 50+ Nigerian Instagram pages (5k\\u2013500k followers) with their rates", "Create a Google Sheet pricing catalog by follower range and niche", "Cold DM 20 businesses/day: \'I can get your brand on 10 Lagos fashion pages for \\u20a680k total\'", "Charge businesses full rate, pay influencers 70\\u201380%, keep 20\\u201330%", "Automate with WhatsApp group connecting brands and creators"]', 0),
('Okrika (UK Used Clothing) Online Store', 'okrika-online', '👗', 'trade', 'Source baled UK/US used clothing from Yaba, Katangua, or Aba markets, handpick quality pieces, and sell via Instagram, WhatsApp, and TikTok. Margins are 300–500%.', 30000, 80000, 'day', 'beginner', 10000, '["Low Capital", "Fashion", "Daily Sales"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Go to Katangua (Lagos), Aba Ariaria, or Onitsha Main Market for bale purchase", "Sort bale: grade A (sell \\u20a63k\\u2013\\u20a615k each), grade B (sell \\u20a6500\\u2013\\u20a62k each)", "Photograph each item on a clean background or mannequin", "Post daily on Instagram Reels + WhatsApp status with prices", "Use GIG Logistics or Kwik for nationwide delivery"]', 0),
('Aba Manufactured Goods Middleman', 'aba-goods-middleman', '🧵', 'trade', 'Source shoes, bags, and clothing directly from Aba manufacturers and supply retailers in your city at 40–60% markup. Aba produces 90% of Nigeria\'s affordable leather goods.', 100000, 300000, 'month', 'intermediate', 30000, '["Scalable", "B2B", "Trading"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Visit Ariaria International Market, Aba for manufacturer contacts (not retailers)", "Sample products: shoes at \\u20a6800\\u2013\\u20a62000 factory price that retail for \\u20a64k\\u2013\\u20a68k", "Place first order of 50\\u2013100 units in popular sizes", "Sell to boutiques, market traders, and Instagram stores in your city", "Build monthly supply chain \\u2014 take orders, travel monthly or use logistics"]', 0),
('POS Super Agent (Multi-Terminal)', 'pos-super-agent', '🏧', 'trade', 'Go beyond single-terminal POS by deploying 5–20 terminals under your super-agent license through OPay, Moniepoint, or Palmpay and earn commission from every transaction processed.', 40000, 100000, 'day', 'intermediate', 200000, '["Daily Cash", "Scalable", "Finance"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Apply for super-agent license: OPay Business, Moniepoint Agency Banking, or PalmPay", "Deploy terminals at high-traffic: markets, bus parks, church areas, campuses", "Hire sub-agents (pay \\u20a65k\\u2013\\u20a615k/day salary or commission split)", "Monitor via agent dashboard app \\u2014 real-time transaction tracking", "Scale to 20+ terminals across different LGAs for maximum daily income"]', 0),
('Assignment & Handwriting Service', 'handwriting-assignment', '✏️', 'education', 'Complete handwritten assignments, practicals, and lab reports for fellow students at ₦500–₦3000 per assignment. High demand during exam periods and submission deadlines.', 5000, 15000, 'day', 'beginner', 0, '["Campus", "No Capital", "Service"]', '["Lagos", "Nationwide", "Online"]', '["Advertise in departmental WhatsApp groups and hostel notice boards", "Set rates by complexity: maths/practicals \\u20a61500\\u2013\\u20a63000, essays \\u20a6500\\u2013\\u20a61500", "Always ask for 50% upfront payment before starting", "Build reputation for accuracy \\u2014 referrals will replace advertising", "Specialize in your department\'s courses for better quality and speed"]', 0),
('Meeting Transcription Service', 'zoom-transcription', '🎤', 'digital', 'Transcribe Zoom, Google Meet, and podcast recordings into clean text documents. International clients pay $0.50–$1.50 per audio minute — a 60-minute meeting earns $30–$90.', 20, 50, 'month', 'beginner', 0, '["Remote", "No Capital", "USD Income"]', '["Online", "Lagos", "Abuja"]', '["Practice on YouTube lectures \\u2014 aim for 60+ words per minute accuracy", "Create profiles on Rev.com, Scribie.com, and TranscribeMe", "Start with lower-paying jobs to build rating and speed", "Apply to Upwork for direct client transcription at $20\\u2013$50/hour", "Use Otter.ai as AI assistant to transcribe first, then clean up manually"]', 1),
('Airtime & Data Reselling (VTU)', 'airtime-data-reselling', '📡', 'trade', 'Become a VTU (Virtual Top-Up) reseller for MTN, Glo, Airtel, and 9mobile and sell data at 3–8% markup. Students, market traders, and small shops buy in volume daily.', 5000, 15000, 'day', 'beginner', 5000, '["Daily Cash", "Low Capital", "Recurring"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Register on VTPass, Gsubz, or Husmo VTU platform (free)", "Fund your wallet with \\u20a610k\\u2013\\u20a620k startup balance", "Set WhatsApp as your storefront \\u2014 post rates daily", "Target bulk buyers: cyber cafes, phone charging shops, mini-marts", "Scale by deploying sub-agents at different locations for passive income"]', 0),
('Student Laundry Service', 'laundry-student', '👕', 'education', 'Offer weekly laundry collection, washing, and delivery for students who hate doing laundry. Charge ₦1500–₦3000 per bag weekly with recurring subscription income.', 8000, 20000, 'day', 'beginner', 5000, '["Campus", "Daily Cash", "No Capital"]', '["Lagos", "Nationwide", "Online"]', '["Advertise in hostel WhatsApp groups: \'Weekly laundry \\u20a62,000 \\u2014 pick up and deliver\'", "Collect every Monday morning, return folded by Wednesday evening", "Use a washing machine if available or hand-wash in batches", "Recruit a partner to scale volume \\u2014 split income 60/40", "Scale to 30+ regular weekly clients = \\u20a660k+ recurring per week"]', 0),
('Canteen Raw Food Supply', 'canteen-food-supply', '🍛', 'trade', 'Supply restaurants, canteens, and food vendors with daily ingredients: tomatoes, onions, peppers, and vegetables bought from Mile 12, Bodija, or local wholesale markets at lower prices.', 15000, 40000, 'day', 'intermediate', 10000, '["B2B", "Daily Cash", "Food"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Visit wholesale market (Mile 12 Lagos, Bodija Ibadan) at 4\\u20136am for best prices", "Identify 5\\u201310 canteens and food vendors in your area", "Offer daily delivery at 5\\u201310% below what they currently pay", "Collect payment daily or weekly \\u2014 build trust first", "Scale with a cargo bike or keke napep for more volume and clients"]', 0),
('Small Chops & Cake Catering', 'cake-small-chops', '🎂', 'trade', 'Supply small chops platters and celebration cakes for birthday parties, naming ceremonies, and office events. One good weekend event can earn ₦20k–₦80k profit.', 30000, 80000, 'week', 'beginner', 10000, '["Events", "Weekend Income", "Food"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Learn: spring rolls, puff puff, samosas, chicken skewers (YouTube, 3 days)", "Buy ingredients from local market \\u2014 start with one event order", "Post photos of your work on WhatsApp status and Instagram Stories", "Collect 70% deposit before every order to fund ingredients", "Build menu: small chops platters \\u20a68k\\u2013\\u20a615k, cakes \\u20a65k\\u2013\\u20a625k by size"]', 0),
('Mobile Barbing Service (Home Service)', 'mobile-barbing', '✂️', 'trade', 'Offer barbering at clients\' homes, offices, and estates — charge 50–100% premium over salon price for the convenience. Growing Lagos/Abuja trend among busy professionals.', 15000, 30000, 'day', 'beginner', 10000, '["Daily Cash", "Skill", "Service"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Invest in quality clippers: Andis, Wahl, or BaByliss (\\u20a68k\\u2013\\u20a620k)", "Create Instagram page with before/after cuts \\u2014 even friends and family", "Price home service: \\u20a62500\\u2013\\u20a65000 per cut (vs \\u20a61000\\u2013\\u20a62000 at barbershop)", "Target estates, corporate estates, and NYSC corpers quarters", "Build a booking system via WhatsApp \\u2014 regular weekly clients = predictable income"]', 0),
('Generator Repair & Servicing', 'generator-repair', '⚡', 'trade', 'With Nigeria\'s constant power cuts, generator repair technicians earn daily from home visits. A good mechanic with basic tools earns ₦8k–₦30k per day on house calls alone.', 20000, 50000, 'day', 'intermediate', 10000, '["High Demand", "Technical", "Service"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Learn from a generator mechanic \\u2014 2\\u20134 week apprenticeship (pay \\u20a65k\\u2013\\u20a610k tip)", "Buy basic tools: multimeter, carburettor cleaner, spark plugs, wrenches", "Advertise on Naijalogic, your estate WhatsApp group, and neighborhood notice boards", "Charge: servicing \\u20a63k\\u2013\\u20a68k, full repair \\u20a610k\\u2013\\u20a650k depending on fault", "Upsell: sell spare parts at markup \\u2014 AVR, carburettors, spark plugs from Alaba market"]', 0),
('Event Chairs & Tables Rental', 'rental-chair-tables', '🪑', 'trade', 'Buy 100–200 plastic chairs and 10–20 folding tables and rent them out for parties, burials, and church programs. One weekend event can rent out your entire stock.', 30000, 80000, 'week', 'intermediate', 80000, '["Passive Income", "Events", "Asset-Based"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Buy 100 plastic chairs (\\u20a6400\\u2013\\u20a6600 each) + 10 folding tables (\\u20a63k\\u2013\\u20a68k each)", "Store in accessible location \\u2014 rented store space \\u20a65k\\u2013\\u20a615k/month", "Advertise in community WhatsApp groups and church notice boards", "Charge \\u20a6100\\u2013\\u20a6200/chair/day, \\u20a6500\\u2013\\u20a61000/table/day + delivery fee", "Hire casuals for setup/teardown \\u2014 charge premium for full setup service"]', 0),
('Keke (Tricycle) Logistics & Delivery', 'keke-logistics', '🛺', 'trade', 'Use a keke napep for goods delivery, market supply runs, and inter-community logistics in addition to or instead of passenger transport. Daily income is more stable than passenger runs.', 15000, 30000, 'day', 'intermediate', 300000, '["Daily Cash", "Transport", "Asset"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Acquire keke via hire purchase from dealers (\\u20a615k\\u2013\\u20a625k monthly repayment)", "Register with GIG Logistics, Kwik Delivery, or MAX as a last-mile partner", "Market to market women for morning supply runs (\\u20a63k\\u2013\\u20a68k per run)", "Add evening passenger service during peak commute hours", "Track daily expenses vs income \\u2014 net profit should be \\u20a65k\\u2013\\u20a615k after fuel and maintenance"]', 0),
('Real Estate Referral Agent', 'real-estate-referral', '🏠', 'trade', 'Connect property buyers and renters with landlords and developers without being a licensed agent. A single successful connection earns ₦50k–₦500k in referral commission.', 200000, 500000, 'month', 'beginner', 0, '["Commission", "No Capital", "High Ticket"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["List all property owners and landlords you know \\u2014 start your property database", "Join Lagos/Abuja property WhatsApp groups where buyers post needs", "Match buyers\' requirements to available properties \\u2014 collect 5\\u201310% commission", "Always sign a referral letter before introducing parties to protect your commission", "Build relationships with 3\\u20135 reputable agents who will split commission on your referrals"]', 0),
('Liquid Soap & Detergent Production', 'soap-liquid-production', '🧼', 'trade', 'Produce and sell liquid soap, dishwashing detergent, and fabric softener using locally sourced chemicals. Profit margins are 200–400% and every household is a potential customer.', 15000, 40000, 'day', 'beginner', 5000, '["Low Capital", "FMCG", "Scalable"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Buy chemicals: SLS, SLES, texapon, caustic soda from chemical markets (Idumota, Onitsha, Alaba)", "Learn recipes on YouTube: \'Nigerian liquid soap making\' \\u2014 2 hours to learn", "Produce first batch of 20\\u201350 litres, bottle in recycled PET bottles", "Sell to neighbours, market women, schools, and offices", "Scale: supply supermarkets, filling stations, and cleaning companies with branded products"]', 0),
('Beginner ICT & Smartphone Training', 'ict-training', '💻', 'digital', 'Teach basic computer skills, smartphone usage, and WhatsApp business to traders, civil servants, and older adults. Weekly classes of 5–10 students each paying ₦3k–₦10k per course.', 50000, 100000, 'month', 'beginner', 10000, '["Recurring", "Community", "Education"]', '["Online", "Lagos", "Abuja"]', '["Create a 4-week curriculum: Week 1 basics, Week 2 internet, Week 3 business tools, Week 4 social media", "Run in your home, a rented hall, or community center (negotiate free/cheap space)", "Charge \\u20a65k\\u2013\\u20a610k per student per 4-week course", "Target civil servant associations, market women cooperatives, and church groups", "Offer corporate training to SMEs at \\u20a650k\\u2013\\u20a6100k for full-team sessions"]', 1),
('Pure Water & Sachet Water Distribution', 'water-sachet-retail', '💧', 'trade', 'Buy sachet water in bags (₦150–₦350 per bag of 20) and resell individually at ₦50–₦100 each at schools, motor parks, churches, and markets. One person can sell 50–100 bags daily.', 8000, 20000, 'day', 'beginner', 2000, '["Daily Cash", "FMCG", "Recurring"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Find nearest sachet water factory \\u2014 buy at factory price (\\u20a6150\\u2013\\u20a6250/bag)", "Get an insulated cooler or shade to keep water cool \\u2014 cold water sells 3x faster", "Set up at: school gates, motor parks, churches, hospitals, construction sites", "Always have change ready \\u2014 \\u20a650 water requires exact change", "Scale: hire boys on commission (\\u20a6500\\u2013\\u20a61000 per bag sold) to cover multiple locations"]', 0),
('TikTok LIVE Gifting Income', 'tiktok-live-gifting', '🎁', 'social', 'Go live on TikTok daily for entertainment, comedy, or motivation and earn from virtual gifts sent by viewers that convert to real cash. Nigerian creators earn ₦5k–₦50k per live session.', 10000, 40000, 'month', 'beginner', 0, '["Phone Only", "Social Media", "Entertainment"]', '["Online", "Lagos", "Abuja"]', '["Open TikTok account and grow to 1,000 followers first (required for LIVE access)", "Go live 2\\u20133 times daily: 30\\u201360 minute sessions (consistency builds gift culture)", "Niche down: comedy skits, Q&A sessions, music performances, cooking live", "Shout out gift senders \\u2014 creates social proof that encourages more gifting", "Collaborate with other LIVE streamers for joint sessions that double viewership"]', 0),
('Facebook Marketplace Hustle', 'facebook-marketplace-hustle', '🛍️', 'digital', 'Source free or cheap items from friends, families, and neighbours and sell them on Facebook Marketplace. People throw away valuable items daily — you turn them into cash.', 10000, 30000, 'day', 'beginner', 10000, '["No Capital", "Reselling", "Local Sales"]', '["Online", "Lagos", "Abuja"]', '["Post items with clear photos and competitive prices on FB Marketplace", "Source: ask friends for old items they no longer need, buy cheap from Jiji urgent sales", "Focus on: old phones, household items, electronics, clothing, furniture", "Always meet in safe public locations \\u2014 GT Bank branches, Shoprite, police stations", "Scale: expand sourcing to estate WhatsApp groups, garage sales, and church donations"]', 1),
('Music Lessons (Piano, Guitar, Voice)', 'music-lessons', '🎹', 'digital', 'Teach musical instruments or voice training to children and adults in your home, church, or community. Weekly lessons of 4–8 students each paying ₦5k–₦15k/month build steady income.', 50000, 120000, 'month', 'beginner', 0, '["Skill-Based", "Recurring", "Community"]', '["Online", "Lagos", "Abuja"]', '["Define your level: beginner, intermediate \\u2014 be honest about your capability", "Advertise in church, estate notice board, and parents WhatsApp groups", "Offer first lesson free to convert interested parties to paid students", "Create a monthly curriculum so parents see structured value for money", "Scale: hire other music teachers, take commission \\u2014 turn it into a music school"]', 1),
('Bulk SMS Marketing Service', 'bulk-sms-service', '📩', 'digital', 'Resell bulk SMS services to local businesses for promotional campaigns. Buy wholesale SMS units at ₦2–₦4 per message and sell to clients at ₦5–₦8 per message with a clean platform.', 20000, 60000, 'month', 'beginner', 5000, '["B2B", "No Capital", "Recurring"]', '["Online", "Lagos", "Abuja"]', '["Register on Termii, Info Bip, or Multitexter as reseller", "Set up branded panel for clients at \\u20a610k\\u2013\\u20a630k setup fee", "Approach businesses: pharmacies, schools, NGOs, restaurants for monthly campaigns", "Charge per campaign (\\u20a615k\\u2013\\u20a650k) or per message (\\u20a65\\u2013\\u20a68/SMS)", "Add value: write the SMS copy for them \\u2014 charge extra \\u20a63k\\u2013\\u20a610k for copywriting"]', 1),
('App-Based Delivery Agent (Glovo/Chowdeck)', 'delivery-agent-app', '🚴', 'trade', 'Sign up as a delivery agent on Glovo, Chowdeck, or Max.ng and earn per delivery. Busy Lagos/Abuja delivery agents complete 15–30 deliveries daily on bicycle or motorcycle.', 10000, 20000, 'day', 'beginner', 50000, '["Daily Cash", "Gig Economy", "Flexible"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Download the rider app: Glovo, Chowdeck, MaxGo, Gokada, or Kwik", "Submit documents: NIN, bank account, guarantor form, valid ID", "Pass background check (3\\u20137 days) and orientation", "Work peak hours: 11am\\u20132pm (lunch), 5pm\\u20139pm (dinner/evening) for maximum orders", "Work 6 days weekly in high-density areas \\u2014 Victoria Island, Ikeja, Lekki, Wuse II"]', 0),
('Beaded Jewelry & Accessories Making', 'bead-jewelry', '📿', 'trade', 'Make and sell beaded necklaces, bracelets, anklets, and waist beads. Social media-driven demand is massive — Nigerian fashion beads sell well both locally and to diaspora buyers.', 10000, 30000, 'day', 'beginner', 3000, '["Creative", "Low Capital", "Fashion"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Buy beads, wire, clasps from Balogun Market (Lagos) or craft stores (\\u20a63k\\u2013\\u20a610k starter)", "Learn basic stringing patterns on YouTube \\u2014 2\\u20133 hours to learn", "Photograph finished pieces on black velvet for professional look", "Sell via WhatsApp Status, Instagram Stories, and Etsy for international sales", "Create sets: necklace + bracelet + anklet at \\u20a65k\\u2013\\u20a615k for higher order value"]', 0),
('Nail Technician (Home Studio)', 'nails-studio', '💅', 'trade', 'Offer nail art, gel nails, acrylic sets, and manicures from your home studio. Regular clients return every 2–3 weeks, creating reliable recurring income with minimal overhead.', 15000, 35000, 'day', 'beginner', 15000, '["Creative", "Recurring Clients", "Daily Cash"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Buy starter kit: gel polishes, UV lamp, nail drill, forms, tips (\\u20a615k\\u2013\\u20a630k)", "Practice on family for 2 weeks \\u2014 build before/after portfolio", "Create Instagram with design tutorials and client results", "Price: simple manicure \\u20a62k, gel \\u20a64k\\u2013\\u20a68k, full acrylic set \\u20a68k\\u2013\\u20a615k", "Build loyalty program: 10th service free \\u2014 keeps clients coming back every 2\\u20133 weeks"]', 0),
('Palm Oil Trading & Distribution', 'palm-oil-trading', '🛢️', 'trade', 'Buy palm oil wholesale from producing states (Ondo, Cross River, Edo) and resell to Lagos, Abuja, and Port Harcourt markets at 20–40% markup. Nigeria\'s most consumed cooking oil.', 60000, 150000, 'month', 'intermediate', 30000, '["Commodity", "B2B", "Trading"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Source directly from palm oil producers in Ondo or Cross River (\\u20a61200\\u2013\\u20a61800/litre vs \\u20a62500\\u2013\\u20a63500 in Lagos)", "Buy minimum 500\\u20131000 litres per trip for worthwhile margins", "Transport in 25-litre kegs (standard market size) via road haulage", "Sell to: supermarkets, restaurants, food processors, market retailers", "Build relationships with 2\\u20133 producer contacts for consistent supply at stable prices"]', 0),
('Spoken English & Accent Coaching', 'english-teaching', '🗣️', 'digital', 'Teach conversational English to Chinese, Korean, Japanese, and European ESL learners on platforms like iTalki and Cambly. Earn $10–$25 per 45-minute session from your phone.', 20, 40, 'month', 'intermediate', 0, '["Remote", "USD Income", "Education"]', '["Online", "Lagos", "Abuja"]', '["Sign up on Cambly (easiest approval), iTalki, or Preply", "Complete your profile video \\u2014 be warm, clear, and energetic", "Set your rate low initially (Cambly pays fixed $0.17/min = $10.20/hr)", "Move to iTalki community tutor after 50+ sessions for higher rates", "Build specialization: business English, IELTS prep, or American accent for premium rates"]', 0),
('Frozen Foods Distribution Business', 'mini-frozen-food', '🧊', 'trade', 'Buy frozen turkey, chicken, fish, and seafood from importers or cold rooms and resell to households, restaurants, and caterers with 15–30% markup. Year-round consistent demand.', 20000, 60000, 'day', 'intermediate', 30000, '["FMCG", "Daily Cash", "Cold Chain"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Source from Mile 1 Diobu (PH), Marina cold rooms (Lagos), or Kano frozen food importers", "Buy in bulk: turkey per carton, chicken per bag \\u2014 30\\u201350% cheaper than retail", "Sell: to households via WhatsApp orders, to restaurants and event caterers", "Rent a deep freezer (\\u20a65k\\u2013\\u20a615k/month) if you don\'t own one", "Build WhatsApp order list \\u2014 send weekly availability messages with prices"]', 0),
('Google Reviews & Social Proof Agency', 'social-proof-reviews', '⭐', 'digital', 'Help local businesses get legitimate Google reviews, testimonials, and social proof by managing their reputation strategy. Businesses pay ₦10k–₦50k monthly for reputation management.', 50000, 150000, 'month', 'beginner', 0, '["B2B", "No Capital", "Service"]', '["Online", "Lagos", "Abuja"]', '["Learn Google Business Profile setup and optimization (free 1-hour course)", "Approach businesses with few or no Google reviews \\u2014 hotels, restaurants, clinics", "Offer: set up + optimize their Google Business Profile for \\u20a615k one-time", "Add monthly retainer: review generation strategy + response management \\u20a610k\\u2013\\u20a630k/month", "Scale to 10 clients = \\u20a6100k\\u2013\\u20a6300k stable monthly income"]', 1),
('Grasscutter (Cane Rat) Farming', 'grasscutter-farming', '🐀', 'trade', 'Farm grasscutters (cane rats) which sell for ₦8000–₦25000 per animal. Lower startup cost than poultry, less disease risk, and grasscutter meat is a delicacy commanding premium prices.', 200000, 500000, 'month', 'intermediate', 30000, '["Agriculture", "Niche", "High Value"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Buy breeding stock: 1 male + 4 females from established farms (\\u20a615k\\u2013\\u20a640k per animal)", "Build housing: wooden or concrete cage with grass bedding (\\u20a610k\\u2013\\u20a630k DIY)", "Feed: guinea grass, sugarcane, cassava peels \\u2014 almost free if you source correctly", "Each female produces 4\\u20138 pups twice yearly \\u2014 exponential growth", "Sell live to restaurants, suya spots, and exotic meat buyers at premium prices"]', 0),
('Supermarket & Kiosk Supply Agent', 'mini-supermarket-supplies', '🛒', 'trade', 'Supply FMCG products (noodles, sardines, beverages, toiletries) to mini-marts, kiosks, and small supermarkets by buying direct from distributors and delivering at competitive prices.', 50000, 150000, 'month', 'intermediate', 30000, '["B2B", "Recurring", "Trading"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Get distributor accounts: Nestl\\u00e9, Unilever, Dangote, Indomie distributors in your area", "Map 30\\u201350 small kiosks and mini-marts in a 5km radius", "Offer weekly delivery at 5\\u201310% lower than what they currently pay", "Collect payment on delivery or net 3 days to build relationships", "Scale with a dispatch rider or keke napep to serve more clients daily"]', 0),
('Hair Extensions Vendor (Wholesale to Retail)', 'hair-vendor', '💇', 'trade', 'Import Brazilian, Peruvian, or Malaysian hair bundles directly from Alibaba or Chinese exporters and sell to Lagos hair stores and salon owners at 40–100% markup.', 100000, 300000, 'month', 'intermediate', 50000, '["Fashion", "B2B", "High Demand"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Research Alibaba for hair vendors with 4+ stars and 100+ reviews", "Order sample: $50\\u2013$100 to test quality before bulk order", "Import via DHL Express (fastest, \\u20a615k\\u2013\\u20a630k) or sea freight (cheapest, 6\\u20138 weeks)", "Sell wholesale to salon owners at \\u20a615k\\u2013\\u20a650k per bundle or retail via Instagram", "Build your own brand label for premium positioning and higher margins"]', 0),
('Google My Business / Local SEO Service', 'local-seo-service', '🔍', 'digital', 'Help local businesses appear on Google Maps and local search results. A properly optimized Google Business Profile can bring 50–200 new customers monthly to a business.', 80000, 200000, 'month', 'beginner', 0, '["B2B", "Recurring", "Digital Marketing"]', '["Online", "Lagos", "Abuja"]', '["Learn Google Business Profile optimization \\u2014 free 3-hour Google course", "Identify businesses not on Google Maps or with incomplete profiles \\u2014 walk your street", "Pitch: \'I\'ll set up and optimize your Google presence so customers find you easily\'", "Charge: \\u20a615k\\u2013\\u20a630k setup, \\u20a610k\\u2013\\u20a620k/month maintenance", "Add: WhatsApp Business setup, photo optimization, review generation for full package"]', 0),
('Secondhand & Out-of-Print Books', 'secondhand-books', '📖', 'trade', 'Collect secondhand university textbooks, WAEC past questions, and professional certification study materials and resell to students at 50–80% of original price. Every university town has constant demand.', 15000, 35000, 'day', 'beginner', 5000, '["Low Capital", "Education", "Niche"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Source: university alumni WhatsApp groups, Jiji, estate garage sales, market clearing sales", "Focus on: current university syllabi textbooks, WAEC/NECO past questions, ICAN/ACCA materials", "Sell at: school gates, university library entrance, Konga/Jiji online listings", "Bundle: sell full semester reading list as package for premium price", "Expand to WhatsApp group: \'Affordable textbooks \\u2014 nationwide delivery\'"]', 0),
('Jumia/Konga Store Manager', 'e-commerce-store-manager', '🛍️', 'digital', 'Manage product listings, inventory, pricing, and fulfillment for business owners selling on Jumia or Konga who lack the time or skill to run their own storefronts optimally.', 80000, 200000, 'month', 'intermediate', 0, '["Remote", "B2B", "Service"]', '["Online", "Lagos", "Abuja"]', '["Learn Jumia/Konga seller center \\u2014 create test account and explore the dashboard", "Build case study: offer to manage a friend\'s products on Jumia for 1 month free", "Document results: \'Increased sales by 40% in 30 days\' = powerful pitch", "Charge: \\u20a620k\\u2013\\u20a650k/month per store or 10\\u201315% of monthly revenue", "Scale to 5 stores = \\u20a6100k\\u2013\\u20a6250k monthly for part-time work"]', 0),
('Courier & Dispatch Motorcycle Business', 'courier-bike-business', '🏍️', 'trade', 'Run an independent dispatch service for businesses, law firms, medical labs, and e-commerce sellers who need reliable same-day delivery. Corporate contracts pay far better than gig apps.', 20000, 50000, 'day', 'intermediate', 150000, '["Daily Cash", "Transport", "Asset"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Register business name + get dispatch board from local government (\\u20a65k\\u2013\\u20a615k)", "Approach law firms, banks, FMCG companies, and medical labs with rate card", "Charge: within Lagos Island \\u20a62k\\u2013\\u20a65k, cross-town \\u20a65k\\u2013\\u20a615k, same-day guaranteed", "Build WhatsApp status presence \\u2014 share your dispatch service details daily", "Scale: hire 3\\u20135 riders, take 30\\u201350% commission from each delivery they make"]', 0),
('Homemade Cooked Food Delivery', 'homemade-food-delivery', '🍲', 'trade', 'Cook and deliver home-style Nigerian meals — jollof rice, egusi soup, ayamase, pepper soup — to busy workers, bachelor apartments, and office workers who crave mama\'s cooking.', 15000, 35000, 'day', 'beginner', 5000, '["Daily Cash", "Food", "WhatsApp"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Define your menu: 3\\u20135 signature dishes you make excellently", "Set prices: small portion \\u20a61000\\u2013\\u20a61500, full meal \\u20a62000\\u2013\\u20a63500 with delivery", "Advertise in bachelor quarters, bachelor pad WhatsApp groups, estate groups", "Use disposable food containers \\u2014 they look professional and hygienic", "Accept weekly subscriptions: \\u20a615k/week for 5 meals = predictable income"]', 0),
('Real Estate Photography', 'real-estate-photography', '🏡', 'trade', 'Photograph properties for real estate agents, landlords, and AirBnB hosts in Lagos and Abuja. Professional photos sell properties 3x faster — agents pay ₦15k–₦50k per property shoot.', 80000, 200000, 'month', 'intermediate', 50000, '["B2B", "Creative", "Recurring"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Build a portfolio: photograph 3\\u20135 properties for free (friends\' homes, church space)", "Learn: wide-angle HDR photography and Lightroom editing for property looks", "Contact: top real estate agents on Instagram and LinkedIn with your portfolio", "Charge: \\u20a615k\\u2013\\u20a625k for apartment, \\u20a630k\\u2013\\u20a650k for full house, \\u20a680k+ for commercial", "Expand to virtual tours with 360\\u00b0 photos \\u2014 premium add-on service for \\u20a620k\\u2013\\u20a650k"]', 0),
('Patent Medicine Store (PPMV)', 'community-pharmacist', '💊', 'trade', 'Open a licensed Patent and Proprietary Medicines Vendors shop and supply OTC medications to your community. Nigeria has 70,000+ such shops generating steady daily cash income.', 25000, 60000, 'day', 'intermediate', 100000, '["License Required", "Daily Cash", "Healthcare"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Get PPMV license from your state NAFDAC/PCN office (\\u20a610k\\u2013\\u20a630k fees)", "Stock core OTC items: paracetamol, malaria drugs, antibiotics, vitamins, condoms", "Location: junction, school area, densely populated residential area", "Buy from wholesale pharmaceutical distributors at 20\\u201340% below retail price", "Add: basic BP check \\u20a6200\\u2013\\u20a6500, referral service to nearby clinics for commission"]', 0),
('Haulage & Truck Logistics Business', 'haulage-truck', '🚛', 'trade', 'A single 10-ton truck on haulage contract earns ₦300k–₦1.2m monthly. FMCG companies, cement companies, and agricultural traders all need reliable truck partners constantly.', 300000, 600000, 'month', 'advanced', 2, '["High Capital", "High Return", "Asset"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Acquire truck: new (\\u20a68m\\u2013\\u20a620m) or fairly used (\\u20a62m\\u2013\\u20a65m) \\u2014 inspect thoroughly before purchase", "Register company with CAC and get road worthiness certificate, permits", "Apply for contracts: Dangote, BUA, Lafarge, Nestl\\u00e9, Coca-Cola logistics tenders", "Join: Association of Logistics Truck Owners for route allocation and industry contacts", "Manage driver carefully \\u2014 CCTV in cab, GPS tracker, and strict maintenance schedule"]', 0),
('Nigerian Agro-Commodity Export', 'agro-export', '🌍', 'trade', 'Export sesame seeds, cashew nuts, ginger, hibiscus (zobo), and shea butter to China, India, and Europe. Nigeria is one of the world\'s top producers — buyers pay dollar prices.', 20000, 100000, 'month', 'advanced', 500000, '["Export", "High Value", "Agricultural"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Register with NEPC (Nigerian Export Promotion Council) \\u2014 free membership", "Choose commodity: sesame (most liquid), cashew (highest value), ginger (good margins)", "Connect with farmers/aggregators in producing states (Kogi, Kaduna, Benue, Edo)", "Get phytosanitary certificate + certificate of origin from NAFDAC/Federal Min of Agriculture", "Find buyers on TradeKey, Alibaba, or through NEPC buyer-matching service"]', 0),
('School/Office Canteen Management', 'canteen-management', '🍽️', 'trade', 'Bid for and run the food canteen in schools, factories, construction sites, and office complexes. Feed 100–500 people daily with a steady per-head fee or revenue share arrangement.', 80000, 200000, 'day', 'intermediate', 50000, '["B2B", "Daily Cash", "Food"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Identify target institutions: private schools, factories, construction sites, oil service companies", "Prepare a proposal: menu, pricing, hygiene standards, team structure", "Pitch directly to facility manager or HR \\u2014 bring food samples to seal the deal", "Price model: \\u20a6500\\u2013\\u20a61500 per meal per person, with guaranteed daily volumes", "Staff with cooks and kitchen assistants \\u2014 focus on management and quality control"]', 0),
('Eyelash Extensions Vendor & Technician', 'eyelash-vendor', '👁️', 'trade', 'Apply eyelash extensions and sell lash supplies to other technicians. Lash extensions last 3–4 weeks, creating automatic repeat clients that book monthly.', 20000, 50000, 'day', 'beginner', 15000, '["Beauty", "Daily Clients", "Recurring"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Learn from YouTube or attend a 1\\u20132 day lash training (\\u20a610k\\u2013\\u20a630k for course)", "Buy starter kit: lashes, glue, tweezers, lash tiles, under-eye pads (\\u20a610k\\u2013\\u20a625k)", "Practice on mannequin head and willing friends for 1\\u20132 weeks", "Instagram: post before/after and time-lapse application videos \\u2014 they go viral easily", "Build repeat client base: offer 30-day fill-in service at 60% of original price"]', 0),
('Domestic Staff Placement Agency', 'housekeeper-placement', '🏠', 'trade', 'Connect families seeking housekeepers, nannies, cooks, and drivers with verified domestic staff seeking employment. Earn placement fees from both employers and job seekers.', 100000, 250000, 'month', 'intermediate', 0, '["Commission", "Service", "Recurring"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Build database: collect domestic worker CVs from your estate, church, and community", "Create simple vetting process: background check, guarantor form, reference letters", "Advertise in estate WhatsApp groups and Facebook groups for Lagos/Abuja families", "Charge employers: 1 month salary as placement fee (\\u20a620k\\u2013\\u20a680k depending on role)", "Add background check premium service for \\u20a65k extra \\u2014 serious employers pay this"]', 0),
('CCTV & Security Camera Installation', 'security-installation', '🔒', 'trade', 'Install CCTV systems, door alarms, and access control for homes, offices, and businesses. Every new building in Nigeria needs security installations — recurring B2B contracts available.', 80000, 200000, 'month', 'intermediate', 20000, '["B2B", "Technical", "High Demand"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Learn CCTV installation: YouTube \'Hikvision installation Nigeria\' \\u2014 1 week free training", "Get tools: crimping tool, cable tester, drill, ladder (\\u20a610k\\u2013\\u20a625k)", "Partner with an electronics supplier at Computer Village for materials at trade price", "Charge: 4-camera home system \\u20a640k\\u2013\\u20a680k installed, office systems \\u20a6100k\\u2013\\u20a6300k", "Market to: estate developers, property managers, school owners, businesses"]', 0),
('Freelance Data Analysis (Excel/Python)', 'data-analyst-freelance', '📊', 'digital', 'Analyze business data, create dashboards, and deliver insights for SMEs and international clients. Excel-level analysis earns ₦50k–₦150k per project; Python/SQL analysts earn $500–$5k.', 200, 800, 'month', 'intermediate', 0, '["Remote", "USD Income", "Technical"]', '["Online", "Lagos", "Abuja"]', '["Master Excel: pivot tables, VLOOKUP, data visualization \\u2014 2-week online course", "Add Python pandas or SQL for premium positioning \\u2014 free on Google Colab", "Build portfolio: analyze 3 public datasets (Nigeria census, economic data) with insights", "Create Upwork profile + apply to \'data analyst\' projects under $200 first", "Move up: BI dashboards in Power BI or Tableau command $500\\u2013$2k per project"]', 0),
('WordPress Website Design', 'freelance-web-design', '🌐', 'digital', 'Build professional websites for Nigerian and international SMEs using WordPress. Basic sites earn ₦50k–₦200k each; full e-commerce stores earn ₦200k–₦1m per project.', 150000, 400000, 'month', 'intermediate', 20000, '["Remote", "USD Income", "Technical"]', '["Online", "Lagos", "Abuja"]', '["Learn WordPress + Elementor: free YouTube full course \\u2014 1 week to build first site", "Buy cheap hosting + domain (Namecheap): \\u20a610k\\u2013\\u20a620k per year", "Build 3 portfolio sites: a restaurant, a portfolio, and an e-commerce demo", "Charge: simple brochure site \\u20a650k\\u2013\\u20a6120k, business site \\u20a6150k\\u2013\\u20a6300k, e-commerce \\u20a6300k\\u2013\\u20a6800k", "Get clients from: local business WhatsApp groups, LinkedIn, Fiverr, and referrals"]', 0),
('Podcast Production Service', 'podcast-production', '🎙️', 'digital', 'Produce, edit, and distribute podcasts for business owners and thought leaders who want to start a show but lack technical skills. A full-service producer earns ₦30k–₦100k per episode.', 80000, 200000, 'month', 'intermediate', 15000, '["Creative", "Remote", "Service"]', '["Online", "Lagos", "Abuja"]', '["Learn Audacity or Adobe Audition: free courses \\u2014 editing, noise reduction, mastering", "Build sample: edit 3 minutes of raw interview audio to professional quality", "Pitch to business owners, pastors, lawyers, and coaches who speak publicly", "Package: recording setup advice + editing + show notes + Spotify/Apple submission", "Charge monthly retainer: 4 episodes/month for \\u20a680k\\u2013\\u20a6150k = predictable income"]', 0),
('Government Document Facilitation', 'birth-certificate-services', '📋', 'trade', 'Help people obtain birth certificates, NIN enrollment, CAC registration, and driver\'s license through the proper channels — charging a service fee for your time and expertise.', 15000, 40000, 'day', 'beginner', 0, '["Service", "Community", "Daily Cash"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Learn the exact process for: NIN, birth cert, CAC, driver\'s license, international passport", "Know EVERY government office, exact fees, and time frames in your state", "Charge: \\u20a63k\\u2013\\u20a610k per document above government fees as your service charge", "Advertise: notice boards at government offices, church bulletins, estate WhatsApp", "Build relationships with mid-level government staff for faster processing"]', 0),
('Market Research & Survey Data Collector', 'market-survey', '📋', 'digital', 'Collect consumer surveys and field data for research companies, NGOs, and brands doing market studies in Nigeria. Earn per completed survey or daily field data collection rate.', 15000, 40000, 'month', 'beginner', 0, '["Remote", "No Capital", "Flexible"]', '["Online", "Lagos", "Abuja"]', '["Register on: GeoPoll, Premise, Samasource, and local research firms", "Apply for field research roles with IPSOS, Nielsen, or local market research firms", "Start with online surveys: SurveyMonkey paid surveys, Toluna, Swagbucks", "Level up: become a field supervisor managing 5\\u201310 data collectors for \\u20a65k\\u2013\\u20a615k/day", "Build a field research team and bid for NGO data collection contracts"]', 0),
('Spiritual & Religious Items Retail', 'spiritual-products', '🕯️', 'trade', 'Sell prayer oils, Bible/Quran accessories, incense, spiritual candles, and church/mosque supplies to the deeply religious Nigerian market. High demand, high margins, no seasonality.', 15000, 40000, 'day', 'beginner', 10000, '["Niche", "Community", "Daily Sales"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Source: Idumota Market (Lagos), Onitsha Market, or Kano central market", "Stock: prayer oils, anointing oil bottles, religious candles, incense, church bulletins", "Sell: church entrance, mosque surroundings, market stalls, and WhatsApp groups", "Target church administrators for bulk orders: bulletins, candles, communion supplies", "Offer customized church items: personalized prayer bottles, branded Bible covers"]', 0),
('Mobile Cinema Business', 'mobile-cinema', '🎬', 'trade', 'Set up outdoor movie screenings at schools, estates, churches, and community events using a projector and generator. Charge per head or get event fees for entertainment packages.', 50000, 120000, 'week', 'intermediate', 80000, '["Events", "Entertainment", "Weekend"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Buy: HD projector (\\u20a630k\\u2013\\u20a680k) + screen/white wall + sound system (\\u20a620k\\u2013\\u20a650k)", "Get generator for outdoor events (rent initially at \\u20a65k\\u2013\\u20a610k per event)", "Contact: estate associations, school PTAs, churches, and community leaders", "Charge: \\u20a6500\\u2013\\u20a61000 per head public show, \\u20a650k\\u2013\\u20a6150k for private event booking", "Add: popcorn, drinks, and snack sales for additional income per screening"]', 0),
('Cooperative / Thrift Contribution Organizer', 'community-lending', '💰', 'trade', 'Organize and manage monthly esusu (thrift contribution) groups for a management fee. A trusted organizer managing 20 people contributing ₦10k/month handles ₦200k/month in funds.', 20000, 50000, 'month', 'beginner', 0, '["Community", "Finance", "Trust-Based"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Recruit 10\\u201320 trusted members: colleagues, church members, market women", "Set rules: monthly contribution \\u20a65k\\u2013\\u20a620k each, monthly payout to one member", "Charge management fee: \\u20a6500\\u2013\\u20a61000 per member per cycle = \\u20a65k\\u2013\\u20a620k/cycle", "Manage via dedicated WhatsApp group \\u2014 send payment reminders, announce winners", "Scale: run 5 different groups simultaneously = \\u20a625k\\u2013\\u20a6100k passive monthly management fees"]', 0),
('Roasted Groundnut & Peanut Business', 'roasted-peanuts', '🥜', 'trade', 'Roast and sell groundnuts at bus stops, parks, school gates, and markets. One of Nigeria\'s oldest and most reliable micro-businesses — capital is minimal, demand is constant.', 5000, 10000, 'day', 'beginner', 2000, '["No Capital", "Daily Sales", "Food"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Buy raw groundnuts from market (\\u20a6500\\u2013\\u20a61000 per paint bucket)", "Roast using firewood or charcoal stove \\u2014 season with salt and seasoning", "Package in transparent bags at \\u20a6100\\u2013\\u20a6500 per pack", "Set up at high traffic points: motor parks, school gates, church/mosque areas", "Scale: add other roasted items \\u2014 cashews, plantain chips, corn \\u2014 diversify your table"]', 0),
('Suya & BBQ Spot', 'suya-spot', '🍢', 'trade', 'Set up an evening suya (spiced skewered beef/chicken) spot near your neighbourhood. A good suya seller in a busy location earns ₦10k–₦40k profit per evening.', 20000, 50000, 'month', 'beginner', 10000, '["Evening Income", "Food", "Daily Cash"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Learn suya spice blend: suya pepper, groundnut powder, ginger, garlic (recipe online)", "Buy coal grill/barrel (\\u20a65k\\u2013\\u20a615k) and basic utensils \\u2014 skewers, mixing bowls", "Source meat: beef or chicken from butchers at wholesale price", "Set up 5\\u20137pm at busy corners: residential junctions, near bars, markets after hours", "Expand: add grilled fish, chicken, and assorted for higher revenue per customer"]', 0),
('Recyclable Waste Collection & Resale', 'waste-recycling', '♻️', 'trade', 'Collect waste paper, plastic bottles, old electronics, and scrap metal from homes and offices and sell to recycling depots. Environmental and profitable — ₦5k–₦20k daily from consistent collection.', 10000, 25000, 'day', 'beginner', 5000, '["No Capital", "Green Business", "Daily Cash"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Find recycling depots in your city: search \'recycling depot\' + your city", "Know current prices: PET plastic \\u20a6150\\u2013\\u20a6300/kg, cardboard \\u20a630\\u2013\\u20a680/kg, aluminium \\u20a6500\\u2013\\u20a6800/kg", "Create collection route: offices on Mon/Wed, estates Tue/Thu, markets Fri", "Partner with estate management to be their official recycling handler \\u2014 volume guarantee", "Expand: hire collectors on commission, become a depot aggregator for higher margins"]', 0),
('Herbal & Natural Wellness Products', 'herbal-products', '🌿', 'trade', 'Produce and sell herbal teas, natural skincare, black soap, and wellness remedies using local Nigerian herbs. Health-conscious Nigerians and diaspora markets pay premium prices.', 15000, 40000, 'day', 'beginner', 5000, '["Health", "Recurring", "Community"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Source: Tejuosho Market (Lagos), Bodija (Ibadan) for dried herbs and botanicals", "Start with: herbal teas (zobo, moringa, ginger-turmeric blend) and black soap", "Brand professionally: white label packaging with ingredient list and claims", "Sell: WhatsApp, Instagram, natural health expos, and church health fairs", "Export angle: diaspora Nigerians in UK/US pay $10\\u2013$30 for authentic Nigerian herbal products"]', 0),
('2D Animation & Motion Graphics', 'animation-design', '🎭', 'digital', 'Create animated explainer videos, motion graphics, and animated ads using tools like Adobe Animate, After Effects, or AI animation tools. One 60-second video earns $100–$1,000.', 500, 2000, 'month', 'intermediate', 0, '["AI", "Creative", "USD Income"]', '["Online", "Lagos", "Abuja"]', '["Learn Adobe After Effects (free trial) or Canva\'s animation features first", "Build portfolio: animate 3 short explainer videos on different topics", "Create Fiverr gig: \'Animated explainer video \\u2014 60 seconds in 3 days\'", "Target: startups needing product explainers, NGOs, e-learning companies", "AI shortcut: use Runway ML or Pika Labs for AI-assisted animation \\u2014 faster production"]', 0),
('Educational Content Creator (YouTube/TikTok)', 'educational-content-creator', '📚', 'social', 'Create educational content explaining Nigerian exam topics, financial literacy, or professional skills in Pidgin or simple English. Education content has long shelf life and builds deep trust.', 30000, 100000, 'month', 'beginner', 0, '["Long Term", "Passive Income", "Education"]', '["Online", "Lagos", "Abuja"]', '["Pick niche: WAEC maths, financial literacy, Nigerian law basics, digital skills", "Post 3\\u20135 videos weekly explaining concepts simply and clearly", "Use: Nigerian examples, Pidgin explanations for complex topics \\u2014 hugely differentiating", "Monetize: YouTube AdSense, sponsored content from edtech companies, paid courses", "Sell digital products: past question compilations, study packs \\u20a61k\\u2013\\u20a65k each"]', 0),
('Dispatch Rider Fleet Manager', 'dispatch-rider-manager', '📦', 'trade', 'Recruit and manage a fleet of dispatch riders, then lease them to logistics companies, restaurants, and e-commerce brands on monthly contracts. Asset-light staffing business model.', 200000, 500000, 'month', 'advanced', 0, '["Scalable", "Transport", "B2B"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Recruit 5\\u201310 verified dispatch riders (background check + guarantor)", "Create management structure: GPS tracking, daily reporting, strict delivery standards", "Approach: restaurants, Jumia, Konga, pharmacies for outsourced delivery contracts", "Charge: \\u20a680k\\u2013\\u20a6150k/month per rider to client; pay rider \\u20a650k\\u2013\\u20a680k salary", "Scale fleet to 30+ riders \\u2014 passive management income from rider spread"]', 0),
('Online Weight Loss & Fitness Coaching', 'weight-loss-coaching', '⚖️', 'digital', 'Coach Nigerian clients on weight loss, meal plans, and fitness routines via WhatsApp or Zoom. Body transformation is a high-willingness-to-pay niche — clients pay monthly for accountability.', 80000, 200000, 'month', 'intermediate', 0, '["Recurring", "Digital", "Health"]', '["Online", "Lagos", "Abuja"]', '["Document your own transformation or help 3 people for free and document results", "Get certified: free ISSA fitness certification or affordable online cert", "Create Instagram/TikTok: daily tips, client transformations, meal prep reels", "Offer 12-week program: personalized meal plan + workout + weekly check-in for \\u20a630k", "Scale: online group coaching for \\u20a610k each x 20 clients = \\u20a6200k for same time investment"]', 0),
('Generator Extension & Neighbourhood Power Selling', 'generator-plug-service', '🔌', 'trade', 'If you own a generator, sell power connections to 5–15 neighbours who don\'t want to run their own generator. Charge ₦3k–₦10k monthly per connection for 24/7 power when NEPA is down.', 50000, 120000, 'month', 'beginner', 0, '["Passive Income", "Community", "Daily Cash"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Survey neighbours\' interest \\u2014 most will pay gladly to avoid generator stress", "Run armoured cable to 5\\u201310 willing subscribers\' meters (hire electrician \\u20a65k\\u2013\\u20a615k)", "Charge monthly subscription: \\u20a63k\\u2013\\u20a610k depending on estate type and generator size", "Collect prepaid monthly \\u2014 don\'t extend credit for power subscription", "Add more subscribers as you scale generator capacity (consider upgrade to 15kVA)"]', 0),
('Laundry & Dry Cleaning Business', 'laundry-dry-cleaning', '👔', 'trade', 'Open a laundry and dry cleaning service targeting corporate professionals, hotels, and restaurants. Weekly collection and return service builds a loyal, paying subscriber base.', 20000, 60000, 'day', 'intermediate', 50000, '["Recurring", "Service", "Daily Cash"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Buy: industrial washing machine (\\u20a680k\\u2013\\u20a6200k) or use commercial laundry (\\u20a6500\\u2013\\u20a62000/load)", "Set up collection service: pick up on Monday, return Wednesday", "Target: corporate estates where workers have no time, hotels for staff uniforms, restaurants for napkins", "Charge: shirts \\u20a6500\\u2013\\u20a61000, suits \\u20a62000\\u2013\\u20a65000, duvet \\u20a63000\\u2013\\u20a68000", "Add express service: 24-hour return at 50% premium \\u2014 professionals gladly pay this"]', 0),
('Personal Stylist & Wardrobe Consultant', 'fashion-stylist', '👗', 'trade', 'Help clients shop for, organize, and style their wardrobes for special occasions, corporate branding, or everyday wear. Charged per session or as part of event preparation packages.', 50000, 150000, 'month', 'beginner', 0, '["Creative", "Service", "Weekend"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Build your own stylish Instagram profile as your living portfolio", "Offer first 3 clients free or discounted styling sessions for testimonials and photos", "Define packages: wardrobe audit \\u20a615k, event styling \\u20a620k\\u2013\\u20a650k, shopping service \\u20a625k+", "Target: corporate professionals pre-interview, brides + bridal party, socialites pre-event", "Partner with fashion brands for co-promotional content and referral commissions"]', 0),
('Farm Produce Aggregator & Distributor', 'agric-distribution', '🌾', 'trade', 'Buy farm produce (tomatoes, yam, plantain, vegetables) directly from farmers in producing states and supply to Lagos, Abuja, or Port Harcourt markets and supermarkets at profit.', 100000, 300000, 'month', 'intermediate', 30000, '["Agriculture", "B2B", "High Volume"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Build farmer contacts in: Benue (yam), Kebbi (onion), Nasarawa (rice), Kogi (cassava)", "Negotiate farm-gate prices \\u2014 30\\u201360% below Lagos/Abuja market prices", "Arrange transportation: bus loads, shared trucks, or your own vehicle", "Sell to: Mile 12 traders, Bodija market, supermarkets with supply contracts", "Systemize: same farmers, same days, same buyers \\u2014 weekly recurring profitable cycle"]', 0),
('Forex Trading (USD/NGN Pairs)', 'forex-trading', '📈', 'trade', 'Trade USD/NGN and major forex pairs using technical analysis. Nigeria\'s volatile exchange rate creates unique opportunities for traders who understand both global and local economic drivers.', 50000, 200000, 'month', 'advanced', 100, '["Finance", "High Potential", "High Risk"]', '["Lagos", "Abuja", "Port Harcourt", "Nationwide"]', '["Learn: TradingView, candlestick patterns, support/resistance, risk management \\u2014 3 months", "Open demo account on Exness, IC Markets, or HF Markets \\u2014 trade for 3 months profitably first", "Deposit minimum $100 \\u2014 risk maximum 1\\u20132% per trade", "Focus on: EUR/USD, USD/NGN (volatile), Gold (XAU/USD) \\u2014 high liquidity pairs", "Join legitimate Nigerian trading communities \\u2014 avoid paid signals and \'gurus\'"]', 0),
('Hostel Room Rental Sub-letting', 'student-hostel-laundry', '🧺', 'education', 'Rent a large hostel room officially and sub-let spaces to fellow students who need accommodation at premium prices. Universities are perennially short of quality student housing.', 30000, 80000, 'month', 'intermediate', 50000, '["Campus", "Asset", "Passive"]', '["Lagos", "Nationwide", "Online"]', '["Rent a large self-contain or flat near campus officially from landlord", "Sub-divide into spaces: 2\\u20134 students can share one room at \\u20a615k\\u2013\\u20a625k each", "Collect upfront: semester basis = \\u20a660k\\u2013\\u20a6100k per student paid at once", "Provide extras: reliable wifi (\\u20a65k/month resold at \\u20a63k per person) for additional income", "Always maintain good relationship with landlord \\u2014 never sub-let without permission or agreement"]', 0),
